def create_O08(df, runID):
    dict_MovTyp_PJT_Factor = {'FirstRailLeg':1, 'LastRailLeg':1, 'RailTransfer':2, 'IntermediateRailLeg':1, 'ToTubeTransfer':0, 'FromTubeTransfer':2, 'OriginTubeTransfer':2, 'DestinationTubeTransfer':2}
    df['PJT_Multiplier'] = df.MovementType.replace(dict_MovTyp_PJT_Factor)
    df['PJT'] = df.TIME*df.PJT_Multiplier + 2*df.WAITTIME
    df['PJT_Pax'] = df.PJT*df.ODTRIPS
    df_out = df.groupby(['OrigCRS', 'DestCRS', 'ATOC'], as_index=False).agg(ODTRIPS=('ODTRIPS', np.mean), InVehicleTime=('TIME', np.sum), WaitTime=('WAITTIME', np.sum), PJT=('PJT', np.sum), Hour=('Hour', np.min), Legs=('TrainUID', 'count'), PJT_Pax=('PJT_Pax', np.sum))

    df_out.to_parquet(f"{runID}_O08_TransferRecords.parquet", index=False, compression=parquetCompression)


def create_O07(runID, O04_output):
    # Define a function that counts the number of elements between two stops (x and y)
    # Define a function that counts the number of elements between two stops (x and y)
    def count_elements_between_stops(crs, x, y):
        try:
            if crs.count(x) != 1:
                return 0

            # Find positions of 'x' and 'y'
            first_index = crs.index(x)
            sec_index = crs.index(y)

            # Check if 'x' comes before 'y', return the count of elements between them
            if first_index < sec_index:
                return sec_index - first_index - 1
            else:
                return 0
        except ValueError:
            # Handle cases where 'x' or 'y' is not found in the list
            return 0
        
    def count_elements_between_stops_final(crs, x, y):
        try:
            # Find positions of 'x' and 'y'
            first_index = crs.index(x)
            sec_index = crs.index(y)

            # Check if 'x' comes before 'y', return the count of elements between them
            if first_index < sec_index:
                return sec_index - first_index - 1
            else:
                return 0
        except ValueError:
            # Handle cases where 'x' or 'y' is not found in the list
            return 0
        
    df1 = pd.read_parquet(O04_output)
   
    df1 = df1[df1['CODE'].isin(routableStations)].reset_index()
    del df1['index']
    df1 = df1[df1['MeanVolTrip(AP)'] >= 1].reset_index()
    df1['CRS'] = df1.apply(lambda row: str(row['CODE']) if row['CRS'] == '' else row['CRS'], axis=1)
    
    # Assign a 'class' to indicate whether boarding or alighting is allowed
    df1['class'] = df1.apply(
        lambda row: '0' if row['AlightAllowed'] == 0 and row['BoardAllowed'] == 0 else '1',
        axis=1
    )
    df1['Arrival'] = df1['Arrival'].apply(lambda x: x[:5])
    
    # Combine 'CRS' and 'class' into one column
    df1['CRS_class'] = df1['CRS'] + ';' + df1['class'] + ';' + df1['Arrival']
    filtered_df = df1
    
    # Group routes by TrainUID and get a list of the CRS chain
    routes = filtered_df.groupby(['TrainUID', 'ATOC', 'OriginCRS', 'DestinationCRS'])['CRS'].agg(','.join).reset_index()
    routes['CRS'] = routes['CRS'].apply(lambda x: x.split(','))
    routes['CRS_class'] = filtered_df.groupby(['TrainUID', 'ATOC', 'OriginCRS', 'DestinationCRS'])['CRS_class'].agg(','.join).reset_index()['CRS_class'].apply(lambda x: x.split())
    routesDIFF = routes[routes['CRS'].apply(lambda x: len(x) != len(set(x)))].reset_index()
    del routesDIFF['index']
    routes = routes[routes['CRS'].apply(lambda x: len(x) == len(set(x)))].reset_index()
    del routes['index']
    
    # Identify all unique CRS pairs (adjacent stops)
    b = []
    for x in range(len(routes)):
        for y in range(len(routes['CRS'][x]) - 1):
            b.append(routes['CRS'][x][y] + ' - ' + routes['CRS'][x][y+1])
    
    # Remove duplicates from CRS pairs list
    c = list(set(b)) 
    
    # Process each unique CRS pair to find relevant stops between them
    d = []
    for x in c:
        f = [s.strip() for s in x.split('-')][0]
        t = [s.strip() for s in x.split('-')][1]
        crs_counts1 = routes['CRS'].apply(lambda crs: count_elements_between_stops(crs, f, t))
        
        # If no stops are found, append the pair as-is
        if crs_counts1.max() == 0:
            d.append((f + ',' + t).split(','))
        else:
            # If stops are found, include the stops in between
            stations = routes.loc[crs_counts1.idxmax()]['CRS']
            start_index = stations.index(f)
            end_index = stations.index(t)
            d.append(stations[start_index:end_index + 1])  
    
    # Create a DataFrame of original pairs and processed routes
    zippedlist = list(zip(c, d))
    df = pd.DataFrame(zippedlist, columns=['Original', 'Processed'])
    
    # Further process the 'Processed' routes to refine route details
    e = []
    for i in range(len(df)):
        data = df['Processed'].iloc[i]
        f = []
        for x in range(len(data) - 1):
            crs_counts1 = df['Processed'].apply(lambda r: count_elements_between_stops(r, df['Processed'].iloc[i][x], df['Processed'].iloc[i][x + 1]))
            if crs_counts1.max() == 0:
                f.append([(df['Processed'].iloc[i][x]) + ',' + df['Processed'].iloc[i][x + 1]])
            else:
                stations = df.loc[crs_counts1.idxmax()]
                f.append([stations['Processed']])
        e.append(f)
    
    # Clean and deduplicate the final routes
    df['FinalRoutes'] = e
    df['FinalRoutes'] = df['FinalRoutes'].apply(lambda x: str(x).replace('[', '').replace(']', '').replace("'", ''))
    df['FinalRoutes'] = df['FinalRoutes'].apply(lambda x: [item.strip() for item in x.split(',')])
    df['FinalRoutes'] = df['FinalRoutes'].apply(lambda x: list(dict.fromkeys(x)))
    
    
    
    # Process routes for each TrainUID
    results = []
    trainUID = []
    
    for gid in (routes['TrainUID']):
        tuid = gid
        routes_test = routes[routes['TrainUID'] == tuid].reset_index()
        e2 = []
        for i in range(len(routes_test)):
            data = routes_test['CRS'].iloc[i]
            new_df = df
            f2 = []
            for x in range(len(data) - 1):
                crs_counts1 = new_df['FinalRoutes'].apply(lambda r: count_elements_between_stops_final(r, data[x], data[x + 1]))
                if crs_counts1.max() == 0:
                    f2.append([(routes_test['CRS'].iloc[i][x]) + ',' + routes_test['CRS'].iloc[i][x + 1]])
                else:
                    stations = new_df.loc[crs_counts1.idxmax()]
                    f2.append(stations['FinalRoutes'])
            e2.append(f2)
        
        # Flatten the list of routes, clean, and deduplicate it
        flattened_list = [item for sublist in e2 for inner_list in sublist for item in inner_list]
        cleaned_list = []
        for item in flattened_list:
            cleaned_item = re.sub(r"[\[\]' ]", "", item)  # Remove brackets and quotes
            cleaned_list.extend(cleaned_item.split(','))
        
        # Ensure unique elements in the route
        unique_list = []
        seen = set()
        for item in cleaned_list:
            if item not in seen:
                unique_list.append(item)
                seen.add(item)
        
        
        first_list = routes[routes['TrainUID'] == tuid]['CRS_class'].iloc[0][0].split(',')
        
        first_dict = {item.split(';')[0]: (int(item.split(';')[1]), item.split(';')[2]) for item in first_list}
        res = []
        last_known_time = ''
        for code in reversed(unique_list):
            if code in first_dict:
                value,time = first_dict[code]
                last_known_time = time
            else:
                value = 2
                time = time = last_known_time
            res.append(f'{code}; {value};{time}')
        results.append([res])
        trainUID.append(tuid)
    
    # Create a final DataFrame with TrainUID and processed routes
    finaldf = pd.DataFrame(results, trainUID).reset_index().rename(columns={'index': 'TrainUID', 0: 'Routes'})
    
    
    finaldf['Routes'] = finaldf['Routes'].apply(lambda x: list(reversed(x)))
    
    
    fixedDiffRoutes = []

    for x in range(len(routesDIFF)):
        original_route = routesDIFF.iloc[x]['CRS_class'][0]  # Example only handles the first entry
        segments = original_route.split(',')


        updated_segments = []
        for i in range(len(segments) - 1):
            # Extract station pairs
            current_stop = segments[i].split(';')[0]
            next_stop = segments[i + 1].split(';')[0]
            pair = f"{current_stop} - {next_stop}"


            if pair in df['Original'].values:
                expanded_stops = df.loc[df['Original'] == pair, 'FinalRoutes'].values[0]

                if len(expanded_stops) > 2:
                    expanded_segments = [
                        f"{stop};2;{segments[i+1].split(';')[2]}"
                        for stop in expanded_stops
                    ]
                    first = [
                        f"{current_stop};{segments[i].split(';')[1]};{segments[i].split(';')[2]}"
                    ]
                    last = [
                        f"{next_stop};{segments[i +1].split(';')[1]};{segments[i+1].split(';')[2]}"
                    ]



                    updated_segments.extend(first)
                    updated_segments.extend(expanded_segments[1:-1])
                    updated_segments.extend(last)

                else:
                    first = [
                        f"{current_stop};{segments[i].split(';')[1]};{segments[i].split(';')[2]}"
                    ]
                    last = [
                        f"{next_stop};{segments[i +1].split(';')[1]};{segments[i+1].split(';')[2]}"
                    ]
                    updated_segments.extend(first)
                    updated_segments.extend(last)

            else:
                # If no expansion is needed, keep the original segment
                updated_segments.append(segments[i])

        # Add the last segment
        updated_segments.append(segments[-1])

        # Join the updated segments back into a string
        updated_route = ','.join(updated_segments)
        route_list = updated_route.split(',')

        # Remove duplicates by converting the list to a set
        unique_routes = list(set(route_list))

        # If you want the output in the original order without duplicates
        unique_routes = list(dict.fromkeys(route_list))
        fixedDiffRoutes.append(unique_routes)
    routesDIFF['Routes'] = fixedDiffRoutes
    
    fixed = routesDIFF[['TrainUID','Routes']]
    
    finaldf = pd.concat([finaldf[['TrainUID','Routes']],fixed]).reset_index()
    del finaldf['index']
    
    finaldf.to_json(f"{runID}_O07_MappedRoutes.json", orient='records', lines=True)

def main():

    #* This script can be run either inside Visum or externally. If running externally, the path to the version file should be provided in the LoadVersion step of the 'if' block below
    #* Running externally will reduce memory consumption as the version file can be closed before the most memory-intensive steps

    quitVisum = False

    if 'Visum' not in globals():
        import win32com.client as com
        import wx
        
        global app
        app = wx.App()
        
        global Visum
        Visum = com.Dispatch("Visum.Visum.240")
        Visum.LoadVersion(r"D:\SRAM Models\Builder\V12\CIF2GTFS\results\M100_09Oct24_noHX_assg.ver")

        quitVisum = True


    tempPath = f"{tempfile.gettempdir()}\\SRAM"
    Path(tempPath).mkdir(parents=True, exist_ok=True)


    flowBundle = False
    #* Change this for station of interest if flowBundle = True
    CRS = 'LBG'

    if flowBundle:
        runFlowBundle(CRS)

    if partOfFullRun:
        path = os.path.dirname(os.path.dirname(__file__))
        input_path = os.path.join(path, "input\\inputs.csv")
        runID = gi.getRunID(input_path)
    else:
        runID = os.path.split(Visum.IO.CurrentVersionFile)[1][:3]

    create_O04(runID)
    create_O05(tempPath, runID)
    create_O06(tempPath, runID)
    create_O07(runID, f"{runID}_O04_StopsAndPasses.parquet")
        
    dfStopPoints = getStopPoints(stopPointCols)
    dfPathLegs, timecode = getPathLegs(pathLegCols, tempPath, flowBundle, quitVisum)
    
    dfPathLegs = dfPathLegs.merge(dfStopPoints, left_on='FROMSTOPPOINTNO', right_on='NO', how='left')
    dfPathLegs.drop(['NO', 'FROMSTOPPOINTNO'], axis=1, inplace=True)
    dfPathLegs.rename({'CODE':'FromCode', 'NAME':'FromPlatform', 'CRS':'FromCRS'}, axis=1, inplace=True)
    dfPathLegs.FromCode.fillna('Tube', inplace=True)
    dfPathLegs.FromPlatform.fillna('Tube', inplace=True)
    dfPathLegs.FromCRS.fillna(dfPathLegs.OrigCRS, inplace=True)

    dfPathLegs = dfPathLegs.merge(dfStopPoints, left_on='TOSTOPPOINTNO', right_on='NO', how='left')
    dfPathLegs.drop(['NO', 'TOSTOPPOINTNO'], axis=1, inplace=True)
    dfPathLegs.rename({'CODE':'ToCode', 'NAME':'ToPlatform', 'CRS':'ToCRS'}, axis=1, inplace=True)
    dfPathLegs.ToCode.fillna('Tube', inplace=True)
    dfPathLegs.ToPlatform.fillna('Tube', inplace=True)
    dfPathLegs.ToCRS.fillna(dfPathLegs.DestCRS, inplace=True)

    del dfStopPoints

    dfPathLegs['Hour'] = dfPathLegs.DEPTIME.dt.hour

    createO02(dfPathLegs, runID)

    tubeMovements = ['FromTubeTransfer', 'ToTubeTransfer', 'OriginTubeTransfer', 'DestinationTubeTransfer']

    for col in ['FromCode', 'ToCode']:
        dfPathLegs[col] = np.where(dfPathLegs.MovementType.isin(tubeMovements),
                                dfPathLegs[col].str.split("_").str[0],
                                dfPathLegs[col])
    

    dfPathLegs = dfPathLegs[['OrigCRS', 
                            'DestCRS', 
                            'PATHINDEX', 
                            'MovementType', 
                            'DEPTIME', 
                            'Hour', 
                            'TIME', 
                            'WAITTIME', 
                            'ODTRIPS', 
                            'FromCode', 
                            'FromPlatform', 
                            'FromCRS', 
                            'ToCode', 
                            'ToPlatform', 
                            'ToCRS', 
                            'TrainUID', 
                            'TrainServiceCode', 
                            'Headcode',
                            'ATOC'
                            ]]
    dfPathLegs['RunID'] = runID
    dfPathLegs.to_parquet(f"{runID}_O01_PathLegs.parquet", index=False, compression=parquetCompression)

    create_O03(dfPathLegs, runID)

    create_O08(dfPathLegs, runID)
    
    Path.unlink(Path(f"{tempPath}\\PuTPathLegs_{timecode}.sqlite3"))
    print("Done")

    path = os.path.dirname(__file__)
    files = [ f'{runID}_O02_StationMovements.json', f'{runID}_O03_ODHourlyRoutes.json', f"{runID}_O04_StopsAndPasses.json", f"{runID}_O07_MappedRoutes.json"]

    with ZipFile(f'{runID}_Results.zip', 'w',  zipfile.ZIP_DEFLATED) as zipObj:
    # Iterate over all the files in directory

            for file in files:
                zipObj.write(os.path.join(path, file), compresslevel=9)
                Path.unlink(os.path.join(path, file))



if __name__ == '__main__':
    main()